import{_ as o,o as n,c as e,a2 as l}from"./chunks/framework.CHeM0PsO.js";const d=JSON.parse('{"title":"说一件小事","description":null,"frontmatter":{"title":"说一件小事","keywords":"公众号更名","date":"2023/03/29 14:03:58","description":null,"tags":["Kotlin","公众号","规划"],"permalink":"/2023/03/29/new-name-and-new-journey/"},"headers":[],"relativePath":"posts/new-name-and-new-journey.md","filePath":"posts/new-name-and-new-journey.md","lastUpdated":1785284005000}'),i={name:"posts/new-name-and-new-journey.md"};function r(a,t,s,p,c,b){return n(),e("div",null,[...t[0]||(t[0]=[l('<blockquote><p>微信公众号 “Kotlin” 即将更名为 “霍丙乾 bennyhuo”，作为我的个人公众号为大家分享技术内容。</p></blockquote><h2 id="微信公众号-kotlin-是怎么来的" tabindex="-1">微信公众号 “Kotlin” 是怎么来的？ <a class="header-anchor" href="#微信公众号-kotlin-是怎么来的" aria-label="Permalink to &quot;微信公众号 “Kotlin” 是怎么来的？&quot;">​</a></h2><p>过去的几年里，我一直专注于研究和推广 Kotlin。从 2016 年开始，我注册了微信公众号 “Kotlin”，用来推送我录制的 Kotlin 入门视频，并且在这个号上面定期发布 Kotlin 相关的技术文章以及组织的各类活动。</p><p><img src="https://kotlinblog-1251218094.costj.myqcloud.com/48cc2b74-2ef8-40db-8418-9d9756bfdf14/media/20230330075842.png" alt=""></p><p>最初，JetBrains 没有在国内投入专门的资源来推广 Kotlin。后来圣佑加入 Kotlin，成为 JetBrains 唯一的中文技术布道师，国内的活动、社区组织也才慢慢走上正轨。同时，在 Google 的助力下，Kotlin 成为大家熟知的现代编程语言，愿意学习 Kotlin 并且愿意输出 Kotlin 内容的开发者也越来越多。</p><p><img src="https://kotlinblog-1251218094.costj.myqcloud.com/48cc2b74-2ef8-40db-8418-9d9756bfdf14/media/20230329205933.png" alt=""></p><p>2020 年写完书之后，我开始研究一些与 Kotlin 关联不大的内容，顺便出了一门 C 语言课。这门课的同学经常催我出一门 C++ 的课，于是我开始在 B 站发 C++ 视频，还写了一系列“渡劫 C++ 协程”的文章。随着我涉猎的内容方向就越来越广泛，这些内容与微信公众号 “Kotlin” 的名字产生了比较大的违和感。</p><p>经过两年时间的探索和思考，我终于下定决心做出一些改变。我向 JetBrains 提了一下我的想法，得到了他们的赞同，于是现在我们终于有了官方的 Kotlin 微信公众号啦！如果大家希望关注 Kotlin 官方的动态，请一定关注官方公众号 “Kotlin开发者”。</p><p><img src="https://kotlinblog-1251218094.costj.myqcloud.com/48cc2b74-2ef8-40db-8418-9d9756bfdf14/media/20230329212925.png" alt=""></p><p>至此，以我个人名义注册的微信公众号 “Kotlin” 已经完成了它的使命。接下来，它将作为我的个人公众号，继续向关注我的朋友们推送我的个人思考和技术分享。</p><h2 id="还会推送-kotlin-相关的内容吗" tabindex="-1">还会推送 Kotlin 相关的内容吗？ <a class="header-anchor" href="#还会推送-kotlin-相关的内容吗" aria-label="Permalink to &quot;还会推送 Kotlin 相关的内容吗？&quot;">​</a></h2><p>当然！</p><p>毫不客气甚至有些骄傲地说，所有编程语言里面，我最擅长的就是 Kotlin。我会持续关注 Kotlin 的最新动态和发展方向，也会与 JetBrains 的朋友们保持联系，在需要的时候参与 Kotlin 相关的活动。</p><p><img src="https://kotlinblog-1251218094.costj.myqcloud.com/48cc2b74-2ef8-40db-8418-9d9756bfdf14/media/20230329214234.png" alt=""></p><p>今年，我还将出版一本 Kotlin 的新书，书名暂定为《深入实践 Kotlin 元编程》，内容主要包括注解处理器、编译器插件等。这些内容基本上是我通过反复阅读 Kotlin 编译器、Jetpack Compose 等项目的源码整理出来的。与《深入理解 Kotlin 协程》类似，这本书的内容对于知识的剖析较为深入，阅读起来有一定的挑战性，相信一定能够给读者带来一些启发。届时，公众号也会推送相关的内容作为补充，方便读者了解其中的细节。</p><p><img src="https://kotlinblog-1251218094.costj.myqcloud.com/48cc2b74-2ef8-40db-8418-9d9756bfdf14/media/20230330070944.png" alt=""></p><p>哦对了，我还是一名 Kotlin GDE，组织上也会要求我们定期输出相关的视频、文章。</p><p><img src="https://kotlinblog-1251218094.costj.myqcloud.com/48cc2b74-2ef8-40db-8418-9d9756bfdf14/media/20230329214632.png" alt=""></p><p>除了 Kotlin 相关的内容以外，我也会输出一些 C/C++、Java、JavaScript 甚至 Rust 相关的内容。具体什么内容可能取决于我那一段时间的兴趣和投入。</p><p>之前有朋友跟我说，其实这些跟 Kotlin 都有关系，因为 Kotlin 要支持多平台嘛。</p><p><img src="https://kotlinblog-1251218094.costj.myqcloud.com/48cc2b74-2ef8-40db-8418-9d9756bfdf14/media/20230330071605.png" alt=""></p><h2 id="目前主要在哪些平台输出内容" tabindex="-1">目前主要在哪些平台输出内容？ <a class="header-anchor" href="#目前主要在哪些平台输出内容" aria-label="Permalink to &quot;目前主要在哪些平台输出内容？&quot;">​</a></h2><p>目前我输出内容的形式主要是文章和视频，在公众号更名之后，发布的平台主要是以下几个：</p><ul><li>Bilibili：<a href="https://space.bilibili.com/28615855" target="_blank" rel="noreferrer"><strong>霍丙乾 bennyhuo</strong></a></li><li>YouTube：<a href="https://www.youtube.com/channel/UCt47g8sEoUkI6R855ol3Gdw" target="_blank" rel="noreferrer"><strong>霍丙乾 bennyhuo</strong></a></li><li>微信公众号：<strong>霍丙乾 bennyhuo</strong></li><li>掘金：<a href="https://juejin.cn/user/1187128286120631" target="_blank" rel="noreferrer"><strong>霍丙乾 bennyhuo</strong></a></li></ul><p>当然，也欢迎大家收藏我的个人主页和 GitHub：</p><ul><li>个人主页：<a href="https://www.bennyhuo.com" target="_blank" rel="noreferrer">https://www.bennyhuo.com</a></li><li>GitHub：<a href="https://github.com/bennyhuo" target="_blank" rel="noreferrer">https://github.com/bennyhuo</a></li></ul><p>感谢大家一如既往的支持。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><p><strong>霍丙乾 bennyhuo</strong>，Google 开发者专家（Kotlin 方向）；<strong>《深入理解 Kotlin 协程》</strong> 作者（机械工业出版社，2020.6）；<strong>《深入实践 Kotlin 元编程》</strong> 作者（机械工业出版社，2023.8）；移动客户端工程师，先后就职于腾讯地图、猿辅导、腾讯视频。</p><ul><li>GitHub：<a href="https://github.com/bennyhuo" target="_blank" rel="noreferrer">https://github.com/bennyhuo</a></li><li>博客：<a href="https://www.bennyhuo.com" target="_blank" rel="noreferrer">https://www.bennyhuo.com</a></li><li>bilibili：<a href="https://space.bilibili.com/28615855" target="_blank" rel="noreferrer"><strong>霍丙乾 bennyhuo</strong></a></li><li>微信公众号：<strong>霍丙乾 bennyhuo</strong></li></ul>',31)])])}const u=o(i,[["render",r]]);export{d as __pageData,u as default};
